class Solution {
public:
    bool isSumEqual(string firstWord, string secondWord, string targetWord) {
        auto numericalValue = [](const string& word) {
            int value = 0;
            for (char c : word) {
                value = value * 10 + (c - 'a');
            }
            return value;
        };

        return numericalValue(firstWord) + numericalValue(secondWord)
               == numericalValue(targetWord);
    }
};
